/* Identidade CRK Paisagismo: terracota #bb7048, verde-acinzentado #445d57, bronze #916442, sálvia #adb5a0, bege #dbd7d0, menta #a4dfc3 (só como acento) */
:root{
  --bg:#ffffff;--fg:#445d57;--muted:#5f736d;--line:#dbd7d0;--card:#f6f4f0;
  --tit:#bb7048;--det:#916442;--accent:#445d57;--accent-fg:#ffffff;
  --pill:#445d57;--pill-fg:#ffffff;--sage:#adb5a0;--mint:#a4dfc3;--stage:#2a3a35;
  --aj-bg:#f3e3d3;--aj-fg:#7a4524;--aj-bd:#bb7048;
  --ok-bg:#a4dfc3;--ok-fg:#1f3a33;--ok-bd:#445d57;
  --no-bg:#916442;--no-fg:#ffffff;--no-bd:#916442;
  --display:'Comfortaa','Trebuchet MS',system-ui,sans-serif;
  --body:'Open Sans',system-ui,-apple-system,'Segoe UI',sans-serif;
}
@media (prefers-color-scheme:dark){
  :root{
    --bg:#16201d;--fg:#e4e1da;--muted:#a9b3aa;--line:#34453f;--card:#1f2b27;
    --tit:#e39a72;--det:#d4ad84;--accent:#a4dfc3;--accent-fg:#16201d;
    --pill:#a4dfc3;--pill-fg:#16201d;--sage:#6f7d72;--stage:#0f1513;
    --aj-bg:#4a3322;--aj-fg:#f0c9a6;--aj-bd:#e39a72;
    --ok-bg:#1f4a3a;--ok-fg:#a4dfc3;--ok-bd:#a4dfc3;
    --no-bg:#5a3d28;--no-fg:#f3dcc4;--no-bd:#d4ad84;
    color-scheme:dark;
  }
}

