/* ao aprovar uma etapa, o Make tira as tags de análise/ajuste dessa mesma etapa */
const LIMPAR={'captado':['Para Captação','Para Capitação'],'ideia aprovada':['Analisar Ideia','Ajustar Ideia','Não entendi a ideia','Ideia não aprovada'],'roteiro aprovado':['Analise Roteiro','Ajustes no Roteiro'],'criativo aprovado':['Análise do criativo','Ajuste no criativo']};
function payload(it){
 const e=etapaDe(it.etapa),i=stat(it);
 return {chave:CHAVE,cliente:CLIENTE,item:it.id,pagina:it.pagina,ts:new Date().toISOString(),etapa:it.etapa,ideia:String(it.numero),titulo:it.titulo,rotulo:'#'+it.numero+' · '+it.titulo,tag:e.tags[i],status:ST_NOTION[e.tags[i]]||'',r1:(LIMPAR[e.tags[i]]||[])[0]||'',r2:(LIMPAR[e.tags[i]]||[])[1]||'',r3:(LIMPAR[e.tags[i]]||[])[2]||'',r4:(LIMPAR[e.tags[i]]||[])[3]||'',obs:(obs[it.id]||'').trim()};
}
